SELECT COUNT(*) AS printing_count
FROM cards
WHERE power IN ('3.5', '4', '5', '6', '7', '8', '9', '10');

SELECT COUNT(DISTINCT CustomerID) FROM (
  SELECT CustomerID FROM transactions_1k WHERE Date LIKE '2012%'
  INTERSECT
  SELECT CustomerID FROM yearmonth WHERE Date LIKE '2012%'
);

SELECT COUNT(*) AS cnt FROM loan l
JOIN account a ON l.account_id = a.account_id
WHERE l.duration = 24 AND a.frequency = 'POPLATEK TYDNE' AND l.status = 'A';

SELECT
  (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'Marvel Comics') -
  (SELECT COUNT(*) FROM superhero s JOIN publisher p ON s.publisher_id = p.id WHERE p.publisher_name = 'DC Comics') AS difference;

SELECT ROUND(AVG(height_cm)*1.0, 1) AS avg_height_cm
FROM superhero
WHERE race_id = 24 AND height_cm IS NOT NULL AND height_cm != 0;

SELECT ROUND(100.0 * COUNT(*) * 1.0 / (SELECT COUNT(*) FROM Examination WHERE Thrombosis > 0), 2) AS PercentageSLEThrombosisPatients
FROM Examination
WHERE Thrombosis > 0 AND Diagnosis LIKE 'SLE%';

